#!/usr/bin/env python3
"""
Round 179b (culprits), 5 October 2026. Needs round 178b.

Salt marsh loss and burned area from NASA.

Run from the repository root (the apply-patch workflow does).
"""
import base64, pathlib, subprocess, sys, tempfile

NOTES = ["## Round 179b (5 October)\n\nNeeds round 178b (guards on its heading). Tiles patch round179b_tiles.py\nbeside it. No app.js?v= bump.\n\n- The owner added the Earthdata login (secrets EARTHDATA_USER and\n  EARTHDATA_PASS in culprits-tiles-more); refresh.yml must pass them in.\n- tiles scripts/lib/earthdata.py: files found through NASA's CMR (no login),\n  downloaded with the login kept for urs.earthdata.nasa.gov only.\n- own_salt_marsh (Oceans > Salt marsh loss): NASA Global Salt Marsh Change\n  2000-2019 (doi:10.3334/ORNLDAAC/2122). sm_loss.tif and sm_gain.tif, cells\n  2000/2005/2010/2015 (period start) or 0, per NASA's guide. tiles\n  salt_marsh.py reads them at full 30 m in the 1-degree squares a Natural\n  Earth 10 m coastline passes through (and neighbours), each 0.005-degree\n  cell the latest period in it, zoom 0-9; values seen are recorded. Tested\n  on a stand-in file. Built once, again by hand.\n- own_burned (Destruction > Fire, first): MODIS MCD64CMQ v061 monthly\n  burned area at 0.25 degree, every year since 2001, summed per year as the\n  share of each cell burned, six steps (RAMP6). The data set, units and\n  scale factor are read from each file and recorded; units it does not\n  understand stop the build. Years built are kept; the year under way is\n  rebuilt daily. Tested with stand-in files (pyhdf, CMR and NASA blocked here).\n"]

DIFF = ""


def git(*a, check=True):
    return subprocess.run(["git", *a], capture_output=True, text=True, check=check)


def main():
    root = pathlib.Path(".")
    if not (root / "map" / "app.js").exists():
        sys.exit("round179b: run from the culprits repository root")
    h = root / "HANDOFF.md"
    if "## Round 178b" not in h.read_text(encoding="utf-8"):
        sys.exit("round179b: round 178b must be applied first")
    with tempfile.NamedTemporaryFile("wb", suffix=".diff", delete=False) as f:
        f.write(base64.b64decode(DIFF))
        path = f.name
    if git("apply", "--check", "-R", path, check=False).returncode == 0:
        print("round179b: already applied")
    else:
        r = git("apply", "--3way", path, check=False)
        if r.returncode != 0:
            git("checkout", "--", "map/app.js", "map/test.mjs", check=False)
            sys.exit("round179b: the diff did not apply:\n" + r.stdout + r.stderr)
        print("round179b: applied")
    text = h.read_text(encoding="utf-8")
    add = "".join(n if n.endswith("\n\n") else n.rstrip("\n") + "\n\n" for n in NOTES if n.split("\n", 1)[0] not in text)
    if add:
        at = text.index("\n## Round ") + 1
        h.write_text(text[:at] + add + text[at:], encoding="utf-8")


if __name__ == "__main__":
    main()
